    {id:"s09", stage:"기본문제", block:"basic_problem", data:{title:"빈대떡과 사과", scenario:{icon:"🥞", body:"사과를 납작 빈대떡 위에 겹쳐 놓았더니 빈대떡이 사방으로 남았어요."}, question:"어느 것이 더 **넓을까요**?", input:"count_input", answer:"납작 빈대떡", note:"풀이: 겹쳤을 때 남는 쪽이 더 넓다 → **빈대떡이 더 넓다**."}, suggested_extras:["t_l7_simple"]},
    {id:"s10", stage:"기본문제", block:"basic_problem", data:{title:"우묵한 그릇과 동그란 공", scenario:{icon:"🥣", body:"우묵한 그릇에는 물을 담을 수 있지만, 동그란 공에는 담을 수 없어요."}, question:"담을 수 있는 양이 더 **많은** 것은?", input:"count_input", answer:"우묵한 그릇", note:"풀이: 공은 속이 막혀 담을 수 없다 → **우묵한 그릇이 더 많이** 담긴다."}, suggested_extras:["q_l7_what"]},
    {id:"s11", stage:"기본문제", block:"match", data:{title:"작품과 비교를 이어요", type:"touch_match", pairs:[{left:{label:"🐍 긴 뱀"}, right:{num:"길이"}},{left:{label:"🍎 사과"}, right:{num:"무게"}},{left:{label:"🥞 납작 빈대떡"}, right:{num:"넓이"}},{left:{label:"🥣 우묵한 그릇"}, right:{num:"들이"}},{left:{label:"🗼 높은 탑"}, right:{num:"높이"}}]}, suggested_extras:["g_l7_match"], tnote:{ask:["왜 그렇게 짝지었는지 말해 볼까요?"], watch:"까닭 없이 감으로 잇는 경우", min:4}},
    {id:"s12", stage:"기본문제", block:"leveled_problem", data:{title:"만들며 견주어요", levels:{"기본":{q:"긴 뱀·짧은 지렁이·긴 막대 중 가장 긴 것을 고르려면 어떻게 할까요?", a:"셋의 한쪽 끝을 맞추어 나란히 놓는다", steps:["끝 맞추기 → 가장 많이 나온 것이 가장 길다"]},"도전":{q:"파랑 탑은 3층, 초록 탑은 5층이에요. 파랑 탑은 초록 탑보다 어떤가요?", a:"더 낮다", steps:["5층이 더 높다 → 3층은 더 낮다"]},"심화":{q:"똑같은 점토 한 덩이로 **길이**가 두드러진 작품과 **넓이**가 두드러진 작품을 하나씩 만들어 봐요. 두 작품의 **무게**는 어떨까요?", a:"여러 답 — 무게는 같다 (같은 점토니까)", open:true}}}, suggested_extras:["x_l7_fair","e_l7_book2"], tnote:{ask:["같은 점토로 만들었다면 무게는 어떨까요?"], watch:"심화의 핵심은 '모양이 달라도 양은 같다'", min:5}},
    {id:"s13", stage:"응용문제", block:"offline_activity", data:{title:"점토 작품 견주기 잔치", type:"group", goal:"모둠 작품을 모아 다섯 가지 비교로 하나씩 말하기", steps:["각자 점토로 작품을 하나 만든다","모둠 책상에 모두 모은다","작품 두 개를 골라 '○○이 △△보다 더 ~다'로 말한다","다섯 가지 비교를 모두 한 번씩 써 본다"], materials:["점토","모둠 책상","작품 이름표"], minutes:8}, suggested_extras:["t_l7_share","r_l7_class"], tnote:{ask:["다섯 가지를 모두 써 보았나요?"], watch:"길이·크기에만 몰리는 모둠 — 들이·높이 유도", min:8}},
    {id:"s14", stage:"응용문제", block:"real_world", data:{title:"집에서도 높이를 견주어요", scenario:{icon:"🛏️", body:"침대보다 책장이 더 높아요. 이것은 무슨 비교일까요?"}, content:"책장과 침대, 형과 나, 나무와 집 — **위로 얼마나 솟았는지**를 견주면 **높이** 비교예요."}, suggested_extras:["r_l7_home","e_l7_tower"]},
    {id:"s15", stage:"응용문제", block:"advanced_problem", data:{title:"생각을 넓혀요", context:"곰이가 점토 뱀을 세워 보았어요.", challenge:"눕혀 놓았을 때는 '더 길다'고 했는데, 세우면 뭐라고 말해야 할까요? 그 까닭도 말해 봐요.", note:"풀이: 세우면 **더 높다**고 말해요. 같은 것이라도 **눕히면 길이, 세우면 높이**로 견주게 돼요."}, suggested_extras:["e_l7_tower"], tnote:{ask:["길이와 높이는 정말 다른 걸까요?"], watch:"1학년 수준에서는 '눕히면 길이·세우면 높이'로 충분", min:4}},
    {id:"s16", stage:"정리", block:"exit_ticket", data:{title:"오늘 확인해요", items:[{q:"위로 얼마나 솟았는지 견주는 말은?", a:"높이 (더 높다·더 낮다)"},{q:"단원에서 배운 비교는 모두 몇 가지?", a:"다섯 가지 (길이·무게·넓이·들이·높이)"},{q:"같은 점토로 모양만 바꾸면 무게는?", a:"그대로 같다"}], self:["다섯 가지 비교를 모두 말할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]}, suggested_extras:[]},
    {id:"s17", stage:"정리", block:"summary", data:{title:"단원에서 만난 다섯 가지", points:["**길이** 더 길다·더 짧다 / **무게** 더 무겁다·더 가볍다","**넓이** 더 넓다·더 좁다 / **들이** 더 많다·더 적다","**높이** 더 높다·더 낮다 — 오늘 새로 배운 말","두 가지 → **더 ~다** / 세 가지 → **가장 ~다**","모양이 달라져도 **점토의 양은 그대로**다."], arrows:["길이","무게","넓이","들이","높이"]}, suggested_extras:["g_l7_match","e_l7_book2"]},
    {id:"s18", stage:"정리", block:"self_assessment", data:{title:"스스로 점검해요", items:["📚 지식·이해 — 다섯 가지 비교(길이·무게·넓이·들이·높이)를 알았나요?","🔧 과정·기능 — '더 ~다·가장 ~다'를 말할 수 있나요?","💛 가치·태도 — 집에서 점토로 만들기를 해 보고 싶나요?"], prompts:["가장 마음에 드는 작품은 무엇이었나요?"]}, suggested_extras:["r_l7_home","e_l7_book2"]},
    {id:"s19", stage:"정리", block:"next_lesson", data:{title:"4단원을 모두 마쳤어요", preview:"곰이와 펭이의 소풍 준비가 끝났어요! 집에서 점토·블록·물·물건들을 견주어 보며 **다섯 가지 비교**를 떠올려 봐요. 다음 단원에서 다시 만나요.", emoji:"🎉"}, suggested_extras:["e_l7_book2","r_l7_home"]}
